import apiClient from './api';

/**
 * List documents with pagination and search.
 * @param {{page?: number, size?: number, keywords?: string}} params
 * @returns {Promise<{total: number, page: number, size: number, records: Array}>}
 */
export async function listDocuments({ page = 1, size = 20, keywords = '' } = {}) {
  const response = await apiClient.get('/documents', {
    params: { page, size, keywords: keywords || undefined },
  });
  return response.data;
}

/**
 * Get a single document by ID.
 * @param {string} id - Document ID
 * @returns {Promise<{id: string, title: string, summary: string, content: string}>}
 */
export async function getDocument(id) {
  const response = await apiClient.get(`/documents/${encodeURIComponent(id)}`);
  return response.data;
}

/**
 * Create a new document.
 * @param {{id: string, title: string, summary?: string, content?: string}} doc
 * @returns {Promise<{id: string, title: string, summary: string, content: string}>}
 */
export async function createDocument(doc) {
  const response = await apiClient.post('/documents', doc);
  return response.data;
}

/**
 * Update an existing document.
 * @param {string} id - Document ID
 * @param {{title: string, summary?: string, content?: string}} data
 * @returns {Promise<{id: string, title: string, summary: string, content: string}>}
 */
export async function updateDocument(id, data) {
  const response = await apiClient.put(`/documents/${encodeURIComponent(id)}`, data);
  return response.data;
}

/**
 * Delete a document by ID.
 * @param {string} id - Document ID
 * @returns {Promise<{deleted: string}>}
 */
export async function deleteDocument(id) {
  const response = await apiClient.delete(`/documents/${encodeURIComponent(id)}`);
  return response.data;
}

function triggerCsvDownload(data) {
  const url = window.URL.createObjectURL(new Blob([data]));
  const link = document.createElement('a');
  link.href = url;
  link.setAttribute('download', 'knowledge_base.csv');
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.URL.revokeObjectURL(url);
}

/**
 * Export all documents as CSV file download.
 */
export async function exportDocuments() {
  const response = await apiClient.get('/documents/export', {
    responseType: 'blob',
  });
  triggerCsvDownload(response.data);
}

/**
 * Export selected documents by IDs as CSV file download.
 * @param {string[]} ids
 */
export async function exportDocumentsByIds(ids) {
  const response = await apiClient.post('/documents/export', { ids }, {
    responseType: 'blob',
  });
  triggerCsvDownload(response.data);
}

/**
 * Import documents from a CSV file.
 * @param {File} file - CSV file to import
 * @returns {Promise<{imported: number, skipped: number, total: number}>}
 */
/**
 * Batch delete documents by IDs.
 * @param {string[]} ids
 * @returns {Promise<{deleted: number}>}
 */
export async function batchDeleteDocuments(ids) {
  const response = await apiClient.post('/documents/batch-delete', { ids });
  return response.data;
}

export async function importDocuments(file) {
  const formData = new FormData();
  formData.append('file', file);
  const response = await apiClient.post('/documents/import', formData, {
    headers: { 'Content-Type': 'multipart/form-data' },
  });
  return response.data;
}
