import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Table,
  Button,
  Input,
  Space,
  Typography,
  message,
  Spin,
  Empty,
  Alert,
  Tooltip,
  Popconfirm,
  Modal,
} from 'antd';
import {
  PlusOutlined,
  DeleteOutlined,
  ReloadOutlined,
  SearchOutlined,
  ExportOutlined,
  UploadOutlined,
  DownloadOutlined,
} from '@ant-design/icons';
import {
  listDocuments,
  deleteDocument,
  batchDeleteDocuments,
  exportDocuments,
  exportDocumentsByIds,
  importDocuments,
} from '../../services/documentService';

const { Text } = Typography;

function DocumentList() {
  const navigate = useNavigate();
  const [documents, setDocuments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchText, setSearchText] = useState('');
  const [deleting, setDeleting] = useState(null);
  const [importing, setImporting] = useState(false);
  const [selectedRowKeys, setSelectedRowKeys] = useState([]);
  const [batchDeleting, setBatchDeleting] = useState(false);
  const [pagination, setPagination] = useState({ current: 1, pageSize: 20, total: 0 });
  const fileInputRef = React.useRef(null);

  const fetchDocuments = useCallback(async (page = 1, size = 20, keywords = '') => {
    setLoading(true);
    setError(null);
    try {
      const data = await listDocuments({ page, size, keywords });
      setDocuments(data.records || []);
      setPagination({ current: data.page, pageSize: data.size, total: data.total });
    } catch (err) {
      setError(err.message || '加载文档失败');
      setDocuments([]);
      setPagination((p) => ({ ...p, total: 0 }));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchDocuments(1, 20, '');
  }, [fetchDocuments]);

  const handleDelete = async (id) => {
    setDeleting(id);
    try {
      await deleteDocument(id);
      message.success('文档已删除');
      // 删除后留在当前页，如果当前页没数据了则回退一页
      const newTotal = pagination.total - 1;
      const maxPage = Math.max(1, Math.ceil(newTotal / pagination.pageSize));
      const page = Math.min(pagination.current, maxPage);
      fetchDocuments(page, pagination.pageSize, searchText);
    } catch (err) {
      message.error(err.message || '删除失败');
    } finally {
      setDeleting(null);
    }
  };

  // 导出：有勾选时导出选中，否则导出全部
  const handleExport = async () => {
    try {
      if (selectedRowKeys.length > 0) {
        await exportDocumentsByIds(selectedRowKeys);
        message.success(`已导出 ${selectedRowKeys.length} 篇文档`);
      } else {
        await exportDocuments();
        message.success('已导出全部文档');
      }
    } catch (err) {
      message.error(err.message || '导出失败');
    }
  };

  // 导入：点击触发文件选择
  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleImportFile = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setImporting(true);
    try {
      const result = await importDocuments(file);
      message.success(`导入完成：成功 ${result.imported} 条，跳过 ${result.skipped} 条，共 ${result.total} 条`);
      fetchDocuments(1, pagination.pageSize, searchText);
    } catch (err) {
      message.error(err.message || '导入失败');
    } finally {
      setImporting(false);
      // 清除 input 以便重复选同一个文件
      e.target.value = '';
    }
  };

  // 批量删除
  const handleBatchDelete = () => {
    Modal.confirm({
      title: `确定删除选中的 ${selectedRowKeys.length} 篇文档？`,
      content: '删除后不可恢复。',
      okText: '删除',
      okType: 'danger',
      cancelText: '取消',
      onOk: async () => {
        setBatchDeleting(true);
        try {
          const result = await batchDeleteDocuments(selectedRowKeys);
          message.success(`已删除 ${result.deleted} 篇文档`);
          setSelectedRowKeys([]);
          fetchDocuments(1, pagination.pageSize, searchText);
        } catch (err) {
          message.error(err.message || '批量删除失败');
        } finally {
          setBatchDeleting(false);
        }
      },
    });
  };

  // 搜索处理：回车触发
  const handleSearch = (value) => {
    setSearchText(value);
    setSelectedRowKeys([]);
    fetchDocuments(1, pagination.pageSize, value);
  };

  // 表格分页变化
  const handleTableChange = (pag) => {
    setSelectedRowKeys([]);
    fetchDocuments(pag.current, pag.pageSize, searchText);
  };

  const columns = [
    {
      title: '#',
      key: 'index',
      width: 50,
      render: (_, __, index) => (pagination.current - 1) * pagination.pageSize + index + 1,
    },
    {
      title: '标题',
      dataIndex: 'title',
      key: 'title',
      width: 260,
      render: (text, record) => (
        <Button
          type="link"
          onClick={() => navigate(`/documents/${encodeURIComponent(record.id)}`)}
          style={{ fontWeight: 500, padding: 0 }}
        >
          {text || '未命名'}
        </Button>
      ),
    },
    {
      title: '摘要',
      dataIndex: 'summary',
      key: 'summary',
      width: 200,
      ellipsis: true,
      render: (text) => (
        <Text type="secondary" ellipsis>{text || '-'}</Text>
      ),
    },
    {
      title: '内容',
      dataIndex: 'content',
      key: 'content',
      ellipsis: true,
      render: (text) => {
        if (!text) return <Text type="secondary">-</Text>;
        // 去掉markdown标记，取纯文本前100字
        const plain = text
          .replace(/^#{1,6}\s+/gm, '')
          .replace(/[*_~`>]/g, '')
          .replace(/!?\[.*?\]\(.*?\)/g, '')
          .replace(/```[\s\S]*?```/g, '')
          .replace(/`[^`]*`/g, '')
          .replace(/<[^>]*>/g, '')
          .replace(/\n+/g, ' ')
          .trim();
        const truncated = plain.length > 100 ? plain.substring(0, 100) + '...' : plain;
        return <Text type="secondary" ellipsis>{truncated || '-'}</Text>;
      },
    },
    {
      title: '操作',
      key: 'actions',
      width: 120,
      render: (_, record) => (
        <Space size="small">
          <Tooltip title="新窗口打开">
            <Button
              type="text"
              icon={<ExportOutlined />}
              size="small"
              onClick={() => window.open(`/#/documents/${encodeURIComponent(record.id)}`, '_blank')}
            />
          </Tooltip>
          <Popconfirm
            title="确定删除此文档？"
            description="删除后不可恢复。"
            onConfirm={() => handleDelete(record.id)}
            okText="删除"
            okType="danger"
            cancelText="取消"
          >
            <Tooltip title="删除">
              <Button
                type="text"
                danger
                icon={<DeleteOutlined />}
                size="small"
                loading={deleting === record.id}
              />
            </Tooltip>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  // --- 仅在首次加载时显示全屏loading ---
  if (loading && documents.length === 0 ) {
    return (
      <div style={{ textAlign: 'center', padding: 80 }}>
        <Spin size="large" tip="正在加载文档列表..." />
      </div>
    );
  }

  // --- 加载出错 ---
  if (error) {
    return (
      <Alert
        type="error"
        message="加载文档失败"
        description={error}
        showIcon
        action={
          <Button size="small" onClick={() => fetchDocuments(1, 20, searchText)} icon={<ReloadOutlined />}>
            重试
          </Button>
        }
        style={{ marginBottom: 16 }}
      />
    );
  }

  return (
    <div>
      <div
        style={{
          marginBottom: 16,
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          flexWrap: 'wrap',
          gap: 8,
        }}
      >
        <Input.Search
          placeholder="搜索标题或摘要..."
          value={searchText}
          onChange={(e) => setSearchText(e.target.value)}
          onSearch={handleSearch}
          allowClear
          style={{ maxWidth: 420 }}
        />
        <Space>
          <Button icon={<ReloadOutlined />} onClick={() => fetchDocuments(pagination.current, pagination.pageSize, searchText)}>
            刷新
          </Button>
          {selectedRowKeys.length > 0 && (
            <Button danger icon={<DeleteOutlined />} onClick={handleBatchDelete} loading={batchDeleting}>
              删除选中({selectedRowKeys.length})
            </Button>
          )}
          <Button icon={<DownloadOutlined />} onClick={handleExport}>
            导出{selectedRowKeys.length > 0 ? `选中(${selectedRowKeys.length})` : '全部'}
          </Button>
          <Button icon={<UploadOutlined />} onClick={handleImportClick} loading={importing}>导入</Button>
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleImportFile}
            accept=".csv"
            style={{ display: 'none' }}
          />
          <Button
            type="primary"
            icon={<PlusOutlined />}
            onClick={() => navigate('/documents/new')}
          >
            新建文档
          </Button>
        </Space>
      </div>

      {documents.length === 0 && !loading ? (
        <Empty
          image={Empty.PRESENTED_IMAGE_SIMPLE}
          description={searchText ? '未找到匹配的文档。' : '暂无文档，请创建您的第一个知识库文档。'}
        >
          <Button
            type="primary"
            icon={<PlusOutlined />}
            onClick={() => navigate('/documents/new')}
          >
            新建文档
          </Button>
        </Empty>
      ) : (
        <Table
          rowSelection={{
            selectedRowKeys,
            onChange: (keys) => setSelectedRowKeys(keys),
          }}
          dataSource={documents}
          columns={columns}
          rowKey="id"
          size="middle"
          loading={loading}
          onChange={handleTableChange}
          pagination={{
            current: pagination.current,
            pageSize: pagination.pageSize,
            total: pagination.total,
            showSizeChanger: true,
            showTotal: (total, range) => `第 ${range[0]}-${range[1]} 条，共 ${total} 条`,
          }}
          locale={{
            emptyText: '暂无文档。',
          }}
        />
      )}
    </div>
  );
}

export default DocumentList;
