import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Button, Spin, Typography, Divider } from 'antd';
import { ArrowLeftOutlined, EditOutlined } from '@ant-design/icons';
import { getDocument } from '../../services/documentService';
import { renderMarkdown, extractTOC } from '../../utils/mdRenderer';
import { useMermaidHtml } from '../../utils/useMermaid';

const { Title, Text } = Typography;

function DocumentDetail() {
  const navigate = useNavigate();
  const { id } = useParams();

  const [doc, setDoc] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);

    getDocument(id)
      .then((data) => {
        if (cancelled) return;
        setDoc(data);
      })
      .catch((err) => {
        if (cancelled) return;
        setError(err.message || '加载文档失败');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => { cancelled = true; };
  }, [id]);

  const html = useMemo(() => renderMarkdown(doc?.content || ''), [doc]);
  const finalHtml = useMermaidHtml(html);
  const tocItems = useMemo(() => extractTOC(doc?.content || ''), [doc]);

  const handleTocClick = (headingId) => {
    const el = document.getElementById(headingId);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: 80 }}><Spin size="large" tip="正在加载文档..." /></div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: 60 }}>
        <Title level={4} type="danger">加载文档失败</Title>
        <Text type="secondary">{error}</Text>
        <br /><br />
        <Button onClick={() => navigate('/documents')} icon={<ArrowLeftOutlined />}>返回列表</Button>
      </div>
    );
  }

  if (!doc) return null;

  return (
    <div style={{ display: 'flex', height: 'calc(100vh - 180px)', gap: 16 }}>
      {/* 正文区域 */}
      <div style={{ flex: 1, overflow: 'auto' }}>
        <div style={{ marginBottom: 16 }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
            <Button icon={<ArrowLeftOutlined />} onClick={() => navigate('/documents')}>返回</Button>
            <Button type="primary" icon={<EditOutlined />}
              onClick={() => navigate(`/documents/${encodeURIComponent(doc.id)}/edit`)}>
              编辑
            </Button>
          </div>
          <Title level={4} style={{ margin: 0 }}>{doc.title || '未命名'}</Title>
        </div>

        {doc.summary && (
          <Text type="secondary" style={{ fontSize: 14, marginBottom: 16, display: 'block' }}>{doc.summary}</Text>
        )}

        <Divider />

        <div
          className="vditor-reset markdown-preview"
          style={{ padding: '8px 0' }}
          dangerouslySetInnerHTML={{ __html: finalHtml }}
        />
      </div>

      {/* 目录 */}
      {tocItems.length > 0 && (
        <div style={{
          width: 200, flexShrink: 0, border: '1px solid #d9d9d9', borderRadius: 6,
          overflow: 'hidden', display: 'flex', flexDirection: 'column', background: '#fafafa',
          alignSelf: 'flex-start', position: 'sticky', top: 0, maxHeight: 'calc(100vh - 200px)',
        }}>
          <div style={{
            padding: '8px 12px', background: '#f0f0f0', borderBottom: '1px solid #d9d9d9',
            fontSize: 13, color: '#666', fontWeight: 600,
          }}>目录</div>
          <div style={{ flex: 1, overflow: 'auto', padding: '8px 0' }}>
            <ul className="toc-list" style={{ listStyle: 'none', margin: 0, padding: 0 }}>
              {tocItems.map((item, index) => (
                <li key={index} className={`toc-item toc-level-${item.level}`}
                  style={{ paddingLeft: 12 + (item.level - 1) * 14, paddingRight: 12, paddingTop: 3, paddingBottom: 3 }}>
                  <button onClick={() => handleTocClick(item.id)}
                    style={{
                      cursor: 'pointer', fontSize: Math.max(12, 14 - item.level), color: '#555',
                      display: 'block', width: '100%', textAlign: 'left', overflow: 'hidden',
                      textOverflow: 'ellipsis', whiteSpace: 'nowrap', padding: '2px 4px',
                      borderRadius: 3, border: 'none', background: 'transparent',
                      fontFamily: 'inherit', transition: 'background 0.15s',
                    }}
                    onMouseEnter={(e) => { e.currentTarget.style.background = '#e6f4ff'; e.currentTarget.style.color = '#1677ff'; }}
                    onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = '#555'; }}
                  >{item.text}</button>
                </li>
              ))}
            </ul>
          </div>
        </div>
      )}
    </div>
  );
}

export default DocumentDetail;
