import MarkdownIt from 'markdown-it';
import markdownItPlantuml from 'markdown-it-plantuml';
import markdownItTextualUml from 'markdown-it-textual-uml';

// markdown-it-inline-plantuml depends on sync-fetch which is Node-only
// and may fail in webpack 5 (CRA 5). Wrap in try-catch.
let inlinePlantumlPlugin = null;
try {
  // eslint-disable-next-line
  const mod = require('markdown-it-inline-plantuml');
  inlinePlantumlPlugin = mod.default || mod;
} catch (e) {
  console.warn(
    'markdown-it-inline-plantuml failed to load (sync-fetch not available in browser). ' +
      'Inline PlantUML diagrams will not be rendered.'
  );
}

// Create markdown-it instance
const md = new MarkdownIt({
  html: true,
  linkify: true,
  typographer: true,
  breaks: true,
});

// Register plugins
md.use(markdownItPlantuml, {
  imageFormat: 'svg',
  server: 'http://www.plantuml.com/plantuml',
});

if (inlinePlantumlPlugin) {
  md.use(inlinePlantumlPlugin, {
    imageFormat: 'svg',
    server: 'http://www.plantuml.com/plantuml',
  });
}

// textual-uml exports as ESM default; handle CJS interop
md.use(markdownItTextualUml.default || markdownItTextualUml);

// Custom fence renderer for mermaid diagrams
const defaultFence =
  md.renderer.rules.fence ||
  function (tokens, idx, options, env, self) {
    return self.renderToken(tokens, idx, options);
  };

md.renderer.rules.fence = function (tokens, idx, options, env, self) {
  const token = tokens[idx];
  const lang = token.info.trim().split(/\s+/)[0];
  if (lang === 'mermaid') {
    // 输出带 mermaid class 的 div，由组件中 mermaid.run() 异步渲染
    const content = token.content
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
    return `<div class="mermaid">${content}</div>`;
  }
  return defaultFence(tokens, idx, options, env, self);
};

// Override heading rendering to add id attributes for TOC anchor linking
const defaultHeadingOpen =
  md.renderer.rules.heading_open ||
  function (tokens, idx, options, env, self) {
    return self.renderToken(tokens, idx, options);
  };

md.renderer.rules.heading_open = function (tokens, idx, options, env, self) {
  const token = tokens[idx];
  const inlineToken = tokens[idx + 1];
  let title = '';
  if (inlineToken && inlineToken.type === 'inline') {
    title = inlineToken.content || '';
  }
  const id = slugify(title);
  token.attrSet('id', id);
  return defaultHeadingOpen(tokens, idx, options, env, self);
};

/**
 * Slugify heading text for use as an anchor ID.
 * Preserves Chinese characters and alphanumerics.
 */
function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^\w一-鿿㐀-䶿豈-﫿-]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-+/g, '-') || 'heading';
}

/**
 * Generate a deduplicated set of heading IDs.
 * Appends numeric suffixes for duplicate headings.
 */
function deduplicateIds(headings) {
  const seen = {};
  return headings.map((h) => {
    let id = h.id;
    if (seen[id] !== undefined) {
      seen[id]++;
      id = `${h.id}-${seen[id]}`;
    } else {
      seen[h.id] = 0;
    }
    return { ...h, id };
  });
}

/**
 * Render markdown content to HTML.
 * @param {string} content - Markdown content
 * @returns {string} HTML string
 */
export function renderMarkdown(content) {
  if (!content) return '';
  try {
    // Reset duplicate heading counters for this render pass
    return md.render(content);
  } catch (e) {
    console.error('Markdown render error:', e);
    return `<div class="md-render-error">Render error: ${e.message}</div>`;
  }
}

/**
 * Extract table of contents from markdown content.
 * @param {string} content - Markdown content
 * @returns {Array<{level: number, text: string, id: string}>}
 */
export function extractTOC(content) {
  if (!content) return [];

  try {
    const tokens = md.parse(content, {});
    const headings = [];

    for (let i = 0; i < tokens.length; i++) {
      const token = tokens[i];
      if (token.type === 'heading_open') {
        const level = parseInt(token.tag.replace('h', ''), 10);
        const inlineToken = tokens[i + 1];
        if (inlineToken && inlineToken.type === 'inline') {
          const text = inlineToken.content || '';
          const id = slugify(text);
          headings.push({ level, text, id });
        }
      }
    }

    return deduplicateIds(headings);
  } catch (e) {
    console.error('TOC extraction error:', e);
    return [];
  }
}
