import React, { useState, useEffect, useRef, useCallback, useMemo, useDeferredValue } from 'react';
import { useNavigate, useParams, useBeforeUnload } from 'react-router-dom';
import { Button, Input, Space, Spin, message, Modal, Typography, Tooltip } from 'antd';
import {
  SaveOutlined,
  ArrowLeftOutlined,
  EyeOutlined,
  UnorderedListOutlined,
  ExclamationCircleOutlined,
} from '@ant-design/icons';
import { getDocument, createDocument, updateDocument } from '../../services/documentService';
import { renderMarkdown, extractTOC } from '../../utils/mdRenderer';
import { generateContentMD5 } from '../../utils/md5';
import { useMermaidHtml } from '../../utils/useMermaid';

const { Text, Title: AntTitle } = Typography;

const EDITOR_CONTAINER_ID = 'vditor-editor-container';
const EDITOR_INIT_TIMEOUT = 10000;

function DocumentEditor() {
  const navigate = useNavigate();
  const { id } = useParams();
  const isEditMode = Boolean(id);

  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [summary, setSummary] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [fetchError, setFetchError] = useState(null);
  const [isDirty, setIsDirty] = useState(false);
  const [editorReady, setEditorReady] = useState(false);
  const [editorError, setEditorError] = useState(null);
  const [showPreview, setShowPreview] = useState(true);
  const [showToc, setShowToc] = useState(true);
  const [useFallbackEditor, setUseFallbackEditor] = useState(false);

  const vditorRef = useRef(null);
  const previewRef = useRef(null);
  const initTimerRef = useRef(null);
  const cssLinkRef = useRef(null);

  const deferredContent = useDeferredValue(content);

  const rawHtml = useMemo(() => renderMarkdown(deferredContent), [deferredContent]);
  const previewHtml = useMermaidHtml(rawHtml);
  const tocItems = useMemo(() => extractTOC(deferredContent), [deferredContent]);

  // --- 编辑模式下获取文档 ---
  useEffect(() => {
    if (!isEditMode) return;
    let cancelled = false;
    setLoading(true);
    setFetchError(null);
    getDocument(id)
      .then((doc) => {
        if (cancelled) return;
        setTitle(doc.title || '');
        setSummary(doc.summary || '');
        setContent(doc.content || '');
      })
      .catch((err) => {
        if (cancelled) return;
        setFetchError(err.message || '加载文档失败');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => { cancelled = true; };
  }, [id, isEditMode]);

  // --- 通过 <script> 标签加载 Vditor（绕过webpack，纯浏览器方式） ---
  useEffect(() => {
    let cancelled = false;

    const loadVditor = () => {
      // 先加载 CSS
      if (!document.querySelector('link[data-vditor-css]')) {
        const link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = '/static/vditor/dist/index.css';
        link.setAttribute('data-vditor-css', 'true');
        document.head.appendChild(link);
        cssLinkRef.current = link;
      }

      const containerEl = document.getElementById(EDITOR_CONTAINER_ID);
      if (!containerEl) {
        if (!cancelled) {
          setEditorError('找不到编辑器容器');
          setUseFallbackEditor(true);
          setEditorReady(true);
        }
        return;
      }

      // 超时保护
      initTimerRef.current = setTimeout(() => {
        if (!cancelled) {
          console.warn('Vditor初始化超时，使用纯文本模式');
          setEditorError('编辑器加载超时，已切换到纯文本编辑模式');
          setUseFallbackEditor(true);
          setEditorReady(true);
        }
      }, EDITOR_INIT_TIMEOUT);

      try {
        // Vditor 通过 script 标签加载后挂载在 window.Vditor
        const VditorClass = window.Vditor;
        if (!VditorClass) {
          throw new Error('window.Vditor 未找到，script 标签可能未正确加载');
        }

        const vditor = new VditorClass(containerEl, {
          mode: 'sv',
          height: '100%',
          width: '100%',
          placeholder: '开始编写Markdown内容...',
          value: content,
          theme: 'classic',
          icon: 'ant',
          lang: 'zh_CN',
          cdn: '/static/vditor',
          lineNumber: true,
          cache: { enable: false },
          toolbar: [
            'headings', 'bold', 'italic', 'strike', '|',
            'quote', 'list', 'ordered-list', 'check', '|',
            'code', 'inline-code', '|',
            'link', 'table', '|',
            'undo', 'redo', '|',
            'fullscreen', 'outline',
          ],
          input(value) {
            setContent(value);
            setIsDirty(true);
          },
          after() {
            if (!cancelled) {
              if (initTimerRef.current) {
                clearTimeout(initTimerRef.current);
                initTimerRef.current = null;
              }
              setEditorReady(true);
            }
          },
        });

        vditorRef.current = vditor;
      } catch (err) {
        console.error('Vditor初始化失败:', err);
        if (!cancelled) {
          if (initTimerRef.current) {
            clearTimeout(initTimerRef.current);
            initTimerRef.current = null;
          }
          setEditorError('编辑器加载失败，已切换到纯文本编辑模式');
          setUseFallbackEditor(true);
          setEditorReady(true);
        }
      }
    };

    // 如果 window.Vditor 已存在（之前加载过），直接初始化
    if (window.Vditor) {
      setTimeout(loadVditor, 200);
      return () => { cancelled = true; };
    }

    // 否则创建 script 标签加载
    const script = document.createElement('script');
    script.src = '/static/vditor/dist/index.min.js';
    script.onload = () => {
      if (!cancelled) setTimeout(loadVditor, 200);
    };
    script.onerror = () => {
      if (!cancelled) {
        console.warn('Vditor脚本加载失败，使用纯文本模式');
        setEditorError('编辑器加载失败，已切换到纯文本编辑模式');
        setUseFallbackEditor(true);
        setEditorReady(true);
      }
    };
    document.body.appendChild(script);

    return () => {
      cancelled = true;
      if (initTimerRef.current) {
        clearTimeout(initTimerRef.current);
        initTimerRef.current = null;
      }
      if (vditorRef.current) {
        try { vditorRef.current.destroy(); } catch (e) { /* ignore */ }
        vditorRef.current = null;
      }
      // 不删除 script/css 标签，下次可以直接复用
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // --- 编辑模式下更新编辑器内容 ---
  useEffect(() => {
    if (editorReady && vditorRef.current && content && isEditMode && !isDirty) {
      try { vditorRef.current.setValue(content); } catch (e) { /* ignore */ }
    }
  }, [editorReady, content, isEditMode, isDirty]);

  // --- 关闭页面前提示 ---
  useBeforeUnload(
    useCallback((event) => { if (isDirty) event.preventDefault(); }, [isDirty])
  );

  // 返回目标：编辑模式回到详情页，新建模式回到列表页
  const backPath = isEditMode ? `/documents/${encodeURIComponent(id)}` : '/documents';

  // --- 导航拦截 ---
  const handleNavigateAway = useCallback(
    (targetPath) => {
      if (isDirty) {
        Modal.confirm({
          title: '有未保存的更改',
          icon: <ExclamationCircleOutlined />,
          content: '您有未保存的更改，确定要离开此页面吗？',
          okText: '放弃并离开',
          okType: 'danger',
          cancelText: '继续编辑',
          onOk: () => { setIsDirty(false); navigate(targetPath); },
        });
      } else {
        navigate(targetPath);
      }
    },
    [isDirty, navigate]
  );

  // --- 保存 ---
  const handleSave = async () => {
    if (!title.trim()) { message.warning('请输入文档标题'); return; }
    if (!summary.trim()) { message.warning('请输入文档摘要'); return; }
    setSaving(true);
    try {
      if (isEditMode) {
        await updateDocument(id, { title: title.trim(), summary: summary.trim(), content });
        message.success('文档更新成功！');
      } else {
        const docId = generateContentMD5(content + Date.now() + Math.random());
        await createDocument({ id: docId, title: title.trim(), summary: summary.trim(), content });
        message.success('文档创建成功！');
      }
      setIsDirty(false);
      navigate(backPath);
    } catch (err) {
      message.error(err.message || '保存失败');
    } finally {
      setSaving(false);
    }
  };

  // --- 目录点击 ---
  const handleTocClick = (headingId) => {
    if (previewRef.current) {
      const el = previewRef.current.querySelector(`#${CSS.escape(headingId)}`);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };

  // --- 加载中 ---
  if (loading) {
    return <div style={{ textAlign: 'center', padding: 80 }}><Spin size="large" tip="正在加载文档..." /></div>;
  }

  // --- 加载出错 ---
  if (fetchError) {
    return (
      <div style={{ textAlign: 'center', padding: 60 }}>
        <AntTitle level={4} type="danger">加载文档失败</AntTitle>
        <Text type="secondary">{fetchError}</Text>
        <br /><br />
        <Space>
          <Button onClick={() => navigate(backPath)} icon={<ArrowLeftOutlined />}>返回</Button>
          <Button onClick={() => window.location.reload()} type="primary">重试</Button>
        </Space>
      </div>
    );
  }

  return (
    <div style={{ height: 'calc(100vh - 140px)', display: 'flex', flexDirection: 'column' }}>
      {/* 标题 + 摘要 */}
      <div style={{ marginBottom: 12, display: 'flex', flexDirection: 'column', gap: 8 }}>
        <Button icon={<ArrowLeftOutlined />} onClick={() => handleNavigateAway(backPath)} style={{ alignSelf: 'flex-start' }}>返回</Button>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
          <Input
            placeholder="请输入文档标题（必填）"
            value={title}
            onChange={(e) => { setTitle(e.target.value); setIsDirty(true); }}
            style={{ flex: 1, minWidth: 200, fontSize: 16, fontWeight: 500 }}
            size="large"
          />
          <Space>
            <Tooltip title={showPreview ? '隐藏预览' : '显示预览'}>
              <Button icon={<EyeOutlined />} type={showPreview ? 'primary' : 'default'} onClick={() => setShowPreview(!showPreview)} />
            </Tooltip>
            <Tooltip title={showToc ? '隐藏目录' : '显示目录'}>
              <Button icon={<UnorderedListOutlined />} type={showToc ? 'primary' : 'default'} onClick={() => setShowToc(!showToc)} />
            </Tooltip>
          </Space>
        </div>
        <Input.TextArea
          placeholder="请输入文档摘要（必填，用于搜索和列表展示）"
          value={summary}
          onChange={(e) => { setSummary(e.target.value); setIsDirty(true); }}
          rows={2} maxLength={500} showCount style={{ fontSize: 13 }}
        />
      </div>

      {/* 编辑器 + 预览 + 目录 */}
      <div style={{ flex: 1, display: 'flex', gap: 8, minHeight: 0, overflow: 'hidden' }}>
        {/* 左侧：编辑器 */}
        <div style={{
          flex: showPreview ? 1 : 2, minWidth: showPreview ? 0 : 400,
          border: '1px solid #d9d9d9', borderRadius: 6, overflow: 'hidden',
          display: 'flex', flexDirection: 'column',
        }}>
          <div style={{
            padding: '4px 12px', background: '#fafafa', borderBottom: '1px solid #d9d9d9',
            fontSize: 12, color: '#999', display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          }}>
            <span>Markdown 编辑器{useFallbackEditor ? '（纯文本模式）' : ''}</span>
            {!editorReady && <Spin size="small" />}
          </div>
          {editorError && (
            <div style={{ padding: '4px 12px', background: '#fffbe6', borderBottom: '1px solid #ffe58f', fontSize: 12, color: '#ad8b00' }}>
              {editorError}
            </div>
          )}
          {useFallbackEditor ? (
            <Input.TextArea
              value={content}
              onChange={(e) => { setContent(e.target.value); setIsDirty(true); }}
              placeholder="开始编写Markdown内容..."
              style={{
                flex: 1, resize: 'none', border: 'none', borderRadius: 0, padding: 12,
                fontFamily: "'SF Mono','Menlo','Monaco','Consolas',monospace", fontSize: 14, lineHeight: 1.6,
              }}
            />
          ) : (
            <div id={EDITOR_CONTAINER_ID} style={{ flex: 1, overflow: 'hidden' }} />
          )}
        </div>

        {/* 中间：预览 */}
        {showPreview && (
          <div style={{
            flex: 1, minWidth: 300, border: '1px solid #d9d9d9', borderRadius: 6,
            overflow: 'hidden', display: 'flex', flexDirection: 'column',
          }}>
            <div style={{ padding: '4px 12px', background: '#fafafa', borderBottom: '1px solid #d9d9d9', fontSize: 12, color: '#999' }}>
              预览
            </div>
            <div
              ref={previewRef}
              className="vditor-reset markdown-preview"
              style={{ flex: 1, overflow: 'auto', padding: '16px 24px' }}
              dangerouslySetInnerHTML={{ __html: previewHtml }}
            />
          </div>
        )}

        {/* 右侧：目录 */}
        {showToc && (
          <div style={{
            width: 200, flexShrink: 0, border: '1px solid #d9d9d9', borderRadius: 6,
            overflow: 'hidden', display: 'flex', flexDirection: 'column', background: '#fafafa',
          }}>
            <div style={{
              padding: '4px 12px', background: '#f0f0f0', borderBottom: '1px solid #d9d9d9',
              fontSize: 12, color: '#666', fontWeight: 600,
            }}>目录</div>
            <div style={{ flex: 1, overflow: 'auto', padding: '8px 0' }}>
              {tocItems.length === 0 ? (
                <div style={{ padding: '12px 16px', color: '#bbb', fontSize: 13, fontStyle: 'italic' }}>暂无标题</div>
              ) : (
                <ul className="toc-list" style={{ listStyle: 'none', margin: 0, padding: 0 }}>
                  {tocItems.map((item, index) => (
                    <li key={index} className={`toc-item toc-level-${item.level}`}
                      style={{ paddingLeft: 12 + (item.level - 1) * 14, paddingRight: 12, paddingTop: 3, paddingBottom: 3 }}>
                      <button onClick={() => handleTocClick(item.id)}
                        style={{
                          cursor: 'pointer', fontSize: Math.max(12, 14 - item.level), color: '#555',
                          display: 'block', width: '100%', textAlign: 'left', overflow: 'hidden',
                          textOverflow: 'ellipsis', whiteSpace: 'nowrap', padding: '2px 4px',
                          borderRadius: 3, border: 'none', background: 'transparent',
                          fontFamily: 'inherit', transition: 'background 0.15s',
                        }}
                        onMouseEnter={(e) => { e.currentTarget.style.background = '#e6f4ff'; e.currentTarget.style.color = '#1677ff'; }}
                        onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; e.currentTarget.style.color = '#555'; }}
                      >{item.text}</button>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        )}
      </div>

      {/* 底部操作栏 */}
      <div style={{ marginTop: 12, display: 'flex', justifyContent: 'flex-end', gap: 8, paddingTop: 8, borderTop: '1px solid #f0f0f0' }}>
        <Button onClick={() => handleNavigateAway(backPath)}>取消</Button>
        {isDirty && <Text type="secondary" style={{ lineHeight: '32px', marginRight: 8, fontSize: 12 }}>有未保存的更改</Text>}
        <Button type="primary" icon={<SaveOutlined />} onClick={handleSave}
          loading={saving} disabled={!title.trim() || !summary.trim()} size="large">
          {isEditMode ? '更新文档' : '创建文档'}
        </Button>
      </div>
    </div>
  );
}

export default DocumentEditor;
