import { useState, useEffect, useRef } from 'react';
import mermaid from 'mermaid';

let initialized = false;
function ensureInit() {
  if (!initialized) {
    mermaid.initialize({ startOnLoad: false, theme: 'default' });
    initialized = true;
  }
}

/**
 * 将 HTML 中的 <div class="mermaid">CODE</div> 异步替换为 SVG，
 * 确保 React 每次渲染时 HTML 都已经是最终形态，不会被冲掉。
 */
export function useMermaidHtml(rawHtml) {
  const [html, setHtml] = useState(rawHtml);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!rawHtml) {
      setHtml('');
      return;
    }

    // 提取 mermaid 代码块
    const re = /<div class="mermaid">([\s\S]*?)<\/div>/g;
    const blocks = [];
    let m;
    while ((m = re.exec(rawHtml)) !== null) {
      blocks.push({ full: m[0], code: decodeMermaidContent(m[1]) });
    }

    if (blocks.length === 0) {
      setHtml(rawHtml);
      return;
    }

    // 异步渲染每个 mermaid 块
    let cancelled = false;
    const seq = ++seqRef.current;
    ensureInit();

    Promise.all(
      blocks.map((b, i) =>
        mermaid
          .render(`mermaid-${seq}-${i}`, b.code)
          .then(({ svg }) => svg)
          .catch((e) => {
            console.warn('Mermaid render error:', e);
            return `<pre>${b.code}</pre>`;
          })
      )
    ).then((svgs) => {
      if (cancelled || seq !== seqRef.current) return;

      let result = rawHtml;
      blocks.forEach((b, i) => {
        result = result.replace(b.full, `<div class="mermaid">${svgs[i]}</div>`);
      });
      setHtml(result);
    });

    return () => {
      cancelled = true;
    };
  }, [rawHtml]);

  return html;
}

function decodeMermaidContent(escaped) {
  return escaped
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"');
}

